            obj = null;
        }
    }
    if (obj == null && DataFormat.class.isAssignableFrom(type)) {
        obj = (T) getCamelContext().resolveDataFormat(name);
    }
    if (obj == null && Language.class.isAssignableFrom(type)) {
        obj = (T) getCamelContext().resolveLanguage(name);
    }
    if (obj != null) {
        code.apply(obj);
    }
}

